#include <stdio.h>
#include <math.h>

#define MAX_N 1000000

int main() {
    int N;
    long long K;
    scanf("%d %lld", &N, &K);

    // Precompute sin values for arcs
    // area = 0.5 * |sin(a) + sin(b) + sin(c)| where a,b,c are central angles
    // For unit circle radius 1, area = 0.5 * |sin(2π*i/N) + sin(2π*j/N) + sin(2π*k/N)|
    // But easier: For chords (i,j,k) arcs lengths (d1,d2,d3) summing to N
    // area = 0.5 * | sin(2π*d1/N) + sin(2π*d2/N) + sin(2π*d3/N) |

    double sin_val[MAX_N];
    for (int i = 0; i < N; i++) {
        sin_val[i] = sin(2.0 * M_PI * i / N);
    }

    long long count = 0;
    double area_k = 0.0;

    // Enumerate distinct (a,b) with a <= b and a+b < N, c = N - a - b
    for (int a = 1; a <= N-2 && count < K; a++) {
        for (int b = a; b <= N-1-a && count < K; b++) {
            int c = N - a - b;
            if (c < b) continue; // ensure a<=b<=c to avoid permutations

            double area = 0.5 * fabs(sin_val[a] + sin_val[b] + sin_val[c]);

            // Count how many triangles have this (a,b,c) combination
            long long ways;
            if (a == b && b == c) {
                ways = N; // equilateral case, only N distinct rotations
            } else if (a == b || b == c) {
                ways = (long long)N * 3; // isosceles but not equilateral
            } else {
                ways = (long long)N * 6; // scalene
            }

            if (count + ways >= K) {
                area_k = area;
                break;
            }
            count += ways;
        }
    }

    printf("%.15f\n", area_k);
    return 0;
}

