typedef struct {
    double area;
    long long count;
} Triangle;

int cmp(const void *a, const void *b) {
    double da = ((Triangle*)a)->area;
    double db = ((Triangle*)b)->area;
    if (da < db) return -1;
    if (da > db) return 1;
    return 0;
}

int main() {
    int N;
    long long K;
    scanf("%d %lld", &N, &K);

    int cap = N*N;
    Triangle *arr = malloc(cap * sizeof(Triangle));
    int sz = 0;

    for (int d1 = 1; d1 <= N/3; d1++) {
        for (int d2 = d1; d2 <= (N-d1)/2; d2++) {
            int d3 = N - d1 - d2;
            double a = 2*PI*d1/N, b = 2*PI*d2/N, c = 2*PI*d3/N;
            double area = 0.5*(sin(a)+sin(b)+sin(c));
            long long cnt;
            if (d1==d2 && d2==d3) cnt = N/3;
            else if (d1==d2 || d2==d3) cnt = N;
            else cnt = 2*N;
            arr[sz].area = area; arr[sz].count = cnt; sz++;
        }
    }
    qsort(arr, sz, sizeof(Triangle), cmp);
    long long cum = 0;
    for (int i = 0; i < sz; i++) {
        cum += arr[i].count;
        if (cum >= K) { printf("%.15f\n", arr[i].area); free(arr); return 0; }
    }
    free(arr);
    return 0;
}

