int main(void) {
    ll N, K;
    if (scanf("%lld %lld", &N, &K) != 2) return 0;

    /*
      Any triangle formed by 3 vertices on a regular N-gon is determined by
      the numbers of polygon edges on the three arcs between consecutive chosen
      vertices around the circle: a,b,c >= 1 and a+b+c = N.

      Its area on the unit circle is:
        A = 1/2 * (sin(2πa/N) + sin(2πb/N) + sin(2πc/N))

      Every unordered triangle corresponds to:
        - 3 rotations if a,b,c are all different
        - 1 rotation if two or three are equal
      So for a fixed unordered triple (a,b,c), the number of actual vertex
      triples producing it is:
        mult = N / cnt
      where cnt = number of distinct cyclic shifts of (a,b,c):
        cnt = 3 if all different
        cnt = 1 if a=b=c
        cnt = 3 if exactly two equal? Actually cyclic shifts are all distinct
            unless all equal, so cnt=3 for not-all-equal.
      Hence:
        mult = N if all equal
        mult = N/3 otherwise? Let's derive carefully.

      Number of ordered starts x and arc sequence (a,b,c) is N.
      The same unordered vertex set is represented by 3 starts (one per chosen
      vertex), unless all equal? Even then still 3 starts but same sequence.
      Therefore each unordered triangle is counted exactly 3 times among starts.
      So multiplicity of an unordered arc multiset is:
        N * (#distinct permutations of a,b,c) / 3
      because for each permutation and each start we get representations.

      Easier standard result:
        if all distinct: N representations over starts/permutations collapse to
            6 equivalent ordered descriptions? Let's avoid complexity.

      Instead enumerate canonical a<=b<=c, and count actual vertex triples:
        - all distinct: 2N
        - exactly two equal: N
        - all equal: N/3
      This is correct and can be verified by orbit counting.

      Since N can be large, enumerate all canonical partitions a<=b<=c, a+b+c=N.
      Count multiplicities, sort by area key, and locate K.

      To avoid floating comparison issues, we sort by computed long double area.
      Equal areas from different partitions may exist, but arbitrary order among
      equal areas is allowed, so sorting by numeric value is fine.
    */

    ll maxStates = (N * N) / 12 + 10; /* rough upper bound for partitions */
    long double *areas = (long double*)malloc(sizeof(long double) * (size_t)maxStates);
    ll *mults = (ll*)malloc(sizeof(ll) * (size_t)maxStates);
    if (!areas || !mults) return 0;

    ll m = 0;
    const long double PI = acosl(-1.0L);

    for (ll a = 1; a <= N / 3; ++a) {
        ll bmin = a;
        ll bmax = (N - a) / 2;
        for (ll b = bmin; b <= bmax; ++b) {
            ll c = N - a - b;
            if (b > c) continue;

            ll mult;
            if (a == b && b == c) mult = N / 3;
            else if (a == b || b == c || a == c) mult = N;
            else mult = 2 * N;

            long double area = 0.5L * (
                sinl(2.0L * PI * (long double)a / (long double)N) +
                sinl(2.0L * PI * (long double)b / (long double)N) +
                sinl(2.0L * PI * (long double)c / (long double)N)
            );

            areas[m] = area;
            mults[m] = mult;
            ++m;
        }
    }

    /* sort indices by area */
    ll *idx = (ll*)malloc(sizeof(ll) * (size_t)m);
    if (!idx) return 0;
    for (ll i = 0; i < m; ++i) idx[i] = i;

    /* simple qsort using global-like captured arrays via static pointers is messy;
       instead sort pairs by packing area and mult into structs. */
    typedef struct {
        long double area;
        ll mult;
    } Item;

    Item *items = (Item*)malloc(sizeof(Item) * (size_t)m);
    if (!items) return 0;
    for (ll i = 0; i < m; ++i) {
        items[i].area = areas[i];
        items[i].mult = mults[i];
    }

    int cmp_item(const void *p1, const void *p2) {
        long double x = ((const Item*)p1)->area;
        long double y = ((const Item*)p2)->area;
        if (x < y) return -1;
        if (x > y) return 1;
        return 0;
    }

    qsort(items, (size_t)m, sizeof(Item), cmp_item);

    ll acc = 0;
    long double ans = 0.0L;
    for (ll i = 0; i < m; ++i) {
        if (acc + items[i].mult >= K) {
            ans = items[i].area;
            break;
        }
        acc += items[i].mult;
    }

    printf("%.12Lf\n", ans);

    free(areas);
    free(mults);
    free(idx);
    free(items);
    return 0;
}

