using namespace std;

using int64 = long long;
using i128 = __int128_t;

static const long double PI = acosl(-1.0L);

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long N, K;
    cin >> N >> K;

    /*
      Any triangle formed by 3 vertices on a regular N-gon can be represented by
      positive integers (a,b,c), a+b+c=N, where these are the arc-step lengths
      between consecutive chosen vertices around the circle.

      Its area is:
        A = 2 * sin(pi*a/N) * sin(pi*b/N) * sin(pi*c/N)

      For a fixed unordered triple {a,b,c}:
      - if all distinct: it corresponds to N different vertex triples
      - if two equal:    it corresponds to N different vertex triples
      - if all equal:    it corresponds to N/3 different vertex triples (only if 3|N)

      So we enumerate all unordered partitions a<=b<=c, a+b+c=N, compute area,
      multiplicity, sort by area, and locate the K-th triangle.
    */

    struct Item {
        long double area;
        long long cnt;
    };

    vector<Item> v;
    v.reserve((size_t)N * (size_t)N / 12 + 10);

    for (long long a = 1; a <= N / 3; ++a) {
        long long bmin = a;
        long long bmax = (N - a) / 2;
        for (long long b = bmin; b <= bmax; ++b) {
            long long c = N - a - b;
            if (b > c) continue;

            long double sa = sinl(PI * (long double)a / (long double)N);
            long double sb = sinl(PI * (long double)b / (long double)N);
            long double sc = sinl(PI * (long double)c / (long double)N);
            long double area = 2.0L * sa * sb * sc;

            long long cnt;
            if (a == b && b == c) cnt = N / 3;
            else cnt = N;

            v.push_back({area, cnt});
        }
    }

    sort(v.begin(), v.end(), [](const Item& x, const Item& y) {
        return x.area < y.area;
    });

    long long pref = 0;
    long double ans = 0;
    for (auto &it : v) {
        if (pref + it.cnt >= K) {
            ans = it.area;
            break;
        }
        pref += it.cnt;
    }

    cout << fixed << setprecision(12) << (double)ans << '\n';
    return 0;
}

