public class Main {
    static int N;
    static long totalTriangles;

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        N = sc.nextInt();
        long K = sc.nextLong();
        totalTriangles = (long) N * (N - 1) * (N - 2) / 6;

        double low = 0.0, high = 1.5; // max area of triangle in unit circle is < 1.299
        for (int iter = 0; iter < 80; iter++) {
            double mid = (low + high) / 2;
            if (countLessEqual(mid) < K) {
                low = mid;
            } else {
                high = mid;
            }
        }
        System.out.printf("%.15f\n", high);
    }

    static long countLessEqual(double area) {
        long count = 0;
        // Fix first vertex at 0, others at a and b (0 < a < b < N)
        for (int a = 1; a < N - 1; a++) {
            double sinA = Math.sin(a * 2 * Math.PI / N);
            // b must be > a
            int lo = a + 1, hi = N - 1, best = a;
            while (lo <= hi) {
                int mid = (lo + hi) / 2;
                double sinB = Math.sin(mid * 2 * Math.PI / N);
                double sinBA = Math.sin((mid - a) * 2 * Math.PI / N);
                double triArea = 0.5 * Math.abs(sinA + sinBA - sinB);
                if (triArea <= area) {
                    best = mid;
                    lo = mid + 1;
                } else {
                    hi = mid - 1;
                }
            }
            count += (best - a);
        }
        return count;
    }
}

