import java.io.*;
import java.util.*;

public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        long nextLong() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);
            long sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            long val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }
    }

    static int N;
    static long K;

    static double[] sinHalf; // sin(pi * d / N)

    static double areaBySides(int a, int b, int c) {
        return 2.0 * sinHalf[a] * sinHalf[b] * sinHalf[c];
    }

    static long countLessThan(double x) {
        long cnt = 0;
        // gaps a,b,c positive integers, a+b+c=N
        // each unordered triangle corresponds to 3 ordered triples (starting vertex choice)
        // so total ordered triples count divided by 3 gives number of triangles.
        for (int a = 1; a <= N - 2; a++) {
            int cPtr = N - a - 1; // largest possible c for current b=1
            for (int b = 1; b <= N - a - 1; b++) {
                if (cPtr < 1) break;
                int maxC = N - a - b;
                if (cPtr > maxC) cPtr = maxC;
                while (cPtr >= 1 && areaBySides(a, b, cPtr) >= x) cPtr--;
                if (cPtr <= 0) break;
                cnt += cPtr;
            }
        }
        return cnt / 3;
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();
        N = (int) fs.nextLong();
        K = fs.nextLong();

        sinHalf = new double[N + 1];
        for (int i = 0; i <= N; i++) {
            sinHalf[i] = Math.sin(Math.PI * i / N);
        }

        // Area = 2 sin(pi*a/N) sin(pi*b/N) sin(pi*c/N), a+b+c=N, a,b,c>=1
        // Binary search the K-th smallest area:
        // countLessThan(mid) < K <= countLessThanOrEqual(mid) conceptually.
        double lo = 0.0, hi = 3.0 * Math.sqrt(3.0) / 4.0; // max area in unit circle

        for (int it = 0; it < 80; it++) {
            double mid = (lo + hi) * 0.5;
            long less = countLessThan(mid);
            if (less < K) hi = mid;
            else lo = mid;
        }

        System.out.printf(Locale.US, "%.12f%n", hi);
    }
}
